def add_minutes_with_day_offset(time_str, minutes):
    hh, mm = time_str.split(':')
    base = int(hh) * 60 + int(mm)

    def normalize(total_minutes):
        days, rem = total_minutes // 1440, total_minutes % 1440
        return days, rem

    day_offset, rem_minutes = normalize(base + minutes)
    hours, mins = rem_minutes // 60, rem_minutes % 60
    return (day_offset, '{:02d}:{:02d}'.format(hours, mins))

