def sort_by_string_length_then_reverse_alpha(words):
    def sort_key(w):
        neg_chars = tuple(-ord(c) for c in w)
        return (len(w), neg_chars)
    return sorted(words, key=sort_key)

def reverse_each_word(s):
    words = s.split(' ')
    reversed_words = []
    for w in words:
        reversed_words.append(w[::-1])
    return ' '.join(reversed_words)

