def digital_root_base(n, b):
    if n < b:
        return n
    digit_sum = 0
    while n > 0:
        digit_sum += n % b
        n //= b
    return digital_root_base(digit_sum, b)

def is_balanced_list(lst):
    from itertools import accumulate
    if not lst:
        return False
    prefix_sums = [0] + list(accumulate(lst))
    total = prefix_sums[-1]
    for i in range(len(lst)):
        left_sum = prefix_sums[i]
        right_sum = total - prefix_sums[i + 1]
        if left_sum == right_sum:
            return True
    return False

