def count_weekday_occurrences_in_month(year, month, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def sakamoto_weekday(y, m, d):
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        yy = y - 1 if m < 3 else y
        return (yy + yy // 4 - yy // 100 + yy // 400 + t[m - 1] + d) % 7

    month_lengths = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    days = month_lengths[month - 1]
    first_dow = (sakamoto_weekday(year, month, 1) - 1) % 7
    offset = (weekday_num - first_dow) % 7
    first_hit = 1 + offset
    return (days - first_hit) // 7 + 1

