def custom_fibonacci(a, b, n):
    seq = [a, b]
    if n < 2:
        return seq[n]
    while len(seq) <= n:
        seq.append(seq[-1] + seq[-2])
    return seq[n]

def count_multiples_in_range(a, b, k):
    remainder = a % k
    first = a if remainder == 0 else a + (k - remainder)
    if first > b:
        return 0
    return (b - first) // k + 1

